//! The "Switch to Garrison WebUI" row inside the Stalwart WebUI.
//!
//! Garrison never changes the Stalwart WebUI's code. nginx adds one script tag
//! to the pages of the location that serves it; the script draws a single menu
//! row with Stalwart's own classes. It shows nothing if Stalwart's layout
//! changes, or unless the user signed in to Garrison turned the switch rows on
//! (`/api/switch`); they are off until then. The tag pins the script by hash
//! (Subresource Integrity), so a changed file is not executed. The operator
//! decides where it applies by including the generated file in that location.

use base64::Engine;
use base64::engine::general_purpose::STANDARD;
use sha2::{Digest, Sha384};

pub const SCRIPT: &str = "stalwart-switch.js";
pub const SNIPPET: &str = "/etc/nginx/snippets/garrison-stalwart-switch.conf";

/// `scheme://host[:port]` of a URL.
pub fn origin(url: &str) -> String {
    let (scheme, rest) = url.split_once("://").unwrap_or(("", url));
    let host = rest.split(['/', '?', '#']).next().unwrap_or_default();
    format!("{scheme}://{host}")
}

/// nginx directives for the location that serves the Stalwart WebUI.
pub fn snippet(public_origin: &str, script: &[u8]) -> String {
    let digest = STANDARD.encode(Sha384::digest(script));
    let base = format!(
        "{}{}/",
        public_origin.trim_end_matches('/'),
        crate::app::INTERFACE
    );
    let tag = format!(
        "<script src=\"{base}{SCRIPT}\" integrity=\"sha384-{digest}\" \
         crossorigin=\"anonymous\" data-garrison=\"{base}\" defer></script>"
    );
    format!(
        "# Generated by `garrison stalwart-switch`; the installer keeps it current.\n\
         # Include it inside the nginx location that serves the Stalwart WebUI (/admin/):\n\
         #   include {};\n\
         sub_filter_once on;\n\
         sub_filter '</head>' '{tag}</head>';\n",
        SNIPPET.replace(".conf", "*.conf")
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn origins_and_snippets() {
        assert_eq!(
            origin("https://admin.example.test/admin/"),
            "https://admin.example.test"
        );
        assert_eq!(
            origin("https://admin.example.test:8443"),
            "https://admin.example.test:8443"
        );
        let text = snippet("https://admin.example.test/", b"(() => {})();");
        assert_eq!(text, include_str!("../tests/fixtures/switch.conf"));
    }
}
